const embeddedLogo = "data:image/jpeg;base64,";

let data = [];
let depots = [];
const awards = ["Gold", "Silver", "Pass", "Fail", "Did Not Attempt"];
let historyStack = [];

const home = document.getElementById("home");
const page = document.getElementById("page");
const backBtn = document.getElementById("backBtn");
const homeBtn = document.getElementById("homeBtn");
const headerTitle = document.getElementById("headerTitle");
const homeLogo = document.getElementById("homeLogo");

document.getElementById("overviewCard").addEventListener("click", showOverview);
document.getElementById("resultsCard").addEventListener("click", showDepotMenu);
document.getElementById("searchCard").addEventListener("click", showSearch);
document.getElementById("navOverview").addEventListener("click", showOverview);
document.getElementById("navResults").addEventListener("click", showDepotMenu);
document.getElementById("navSearch").addEventListener("click", showSearch);
backBtn.addEventListener("click", goBack);
homeBtn.addEventListener("click", showHome);

function awardClass(award) {
  if (award === "Gold") return "gold";
  if (award === "Silver") return "silver";
  if (award === "Pass") return "pass";
  if (award === "Fail") return "fail";
  return "dna";
}

function medal(award) {
  if (award === "Gold") return "🥇";
  if (award === "Silver") return "🏅";
  if (award === "Pass") return "🥉";
  if (award === "Fail") return "🔴";
  return "⚫";
}

function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, char => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#039;"
  }[char]));
}

function saveState() {
  historyStack.push({
    homeDisplay: home.style.display || "block",
    pageHTML: page.innerHTML,
    pageDisplay: page.style.display || "none",
    title: headerTitle.textContent
  });
}

function setActiveNav(mode) {
  document.querySelectorAll(".nav-item").forEach(btn => btn.classList.remove("active"));
  if (mode === "overview") document.getElementById("navOverview").classList.add("active");
  if (mode === "results") document.getElementById("navResults").classList.add("active");
  if (mode === "search") document.getElementById("navSearch").classList.add("active");
}

function showHome() {
  home.style.display = "block";
  page.style.display = "none";
  backBtn.style.display = "none";
  homeBtn.style.display = "none";
  historyStack = [];
  headerTitle.textContent = "9AMB IPPT SCORING DASHBOARD";
}

function goBack() {
  if (!historyStack.length) {
    showHome();
    return;
  }

  const state = historyStack.pop();
  home.style.display = state.homeDisplay;
  page.innerHTML = state.pageHTML;
  page.style.display = state.pageDisplay;
  headerTitle.textContent = state.title;

  if (state.pageDisplay === "block") {
    backBtn.style.display = "block";
    homeBtn.style.display = "block";
  } else {
    backBtn.style.display = "none";
    homeBtn.style.display = "none";
  }

  window.scrollTo(0, 0);
}

function showPage(html, title, navMode) {
  saveState();
  home.style.display = "none";
  page.innerHTML = html;
  page.style.display = "block";
  backBtn.style.display = "block";
  homeBtn.style.display = "block";
  headerTitle.textContent = title || "9AMB IPPT SCORING DASHBOARD";
  setActiveNav(navMode);
  window.scrollTo(0, 0);
}

function participantRows(list, showPoints = false) {
  return [...list]
    .sort((a, b) => String(a.tag).localeCompare(String(b.tag)))
    .map(person => `
      <div class="person" onclick="showScorecard('${escapeHtml(person.tag)}')">
        <div>
          <b>#${escapeHtml(person.tag)} - ${escapeHtml(person.name)}</b>
          <div class="muted">${escapeHtml(person.depot)}</div>
        </div>
        ${showPoints ? `
          <div class="points ${awardClass(person.award)}">
            <small>Points</small>
            <strong>${person.score}</strong>
          </div>
        ` : ""}
      </div>
    `)
    .join("");
}

function showOverview() {
  const summary = `
    <div class="panel">
      <h2>OVERVIEW</h2>
      <div class="summary-row">
        <b>Total Participants Registered</b>
        <span class="count">${data.length}</span>
      </div>
      <h2 class="section-title">BY DEPOTS</h2>
      ${depots.map(depot => `
        <div class="summary-row" onclick="showOverviewDepot('${escapeHtml(depot)}')">
          <b>🏢 ${escapeHtml(depot)}</b>
          <span><b class="count">${data.filter(person => person.depot === depot).length}</b> <span class="arrow">›</span></span>
        </div>
      `).join("")}
    </div>
  `;

  showPage(summary, "OVERVIEW", "overview");
}

function showOverviewDepot(depot) {
  const list = data.filter(person => person.depot === depot);
  showPage(`
    <div class="panel">
      <h2>OVERVIEW - ${escapeHtml(depot)}</h2>
      <div class="summary-row">
        <b>Total Participants Registered</b>
        <span class="count">${list.length}</span>
      </div>
      <h2 class="section-title">NAMELIST</h2>
      ${participantRows(list, false) || "<p>No records found.</p>"}
    </div>
  `, `OVERVIEW - ${depot}`, "overview");
}

function showDepotMenu() {
  const html = `
    <div class="results-logo">🏆</div>
    <div class="panel">
      <h2>RESULTS & AWARDS</h2>
      <p class="muted">Select depot</p>
      ${depots.map(depot => `
        <div class="person" onclick="showDepot('${escapeHtml(depot)}')">
          <div>
            <b>🏢 ${escapeHtml(depot)}</b>
            <div class="muted">${data.filter(person => person.depot === depot).length} registered</div>
          </div>
          <div class="arrow">›</div>
        </div>
      `).join("")}
    </div>
  `;

  showPage(html, "RESULTS & AWARDS", "results");
}

function showDepot(depot) {
  const list = data.filter(person => person.depot === depot);

  const summary = `
    <div class="grid">
      <div class="box">
        <small>Total Participants Registered</small>
        <strong>${list.length}</strong>
      </div>
      ${awards.map(award => `
        <div class="box ${awardClass(award)}">
          <small>${medal(award)} ${award}</small>
          <strong>${list.filter(person => person.award === award).length}</strong>
        </div>
      `).join("")}
    </div>
  `;

  const names = awards.map(award => {
    const filtered = list.filter(person => person.award === award);
    return filtered.length
      ? `<h2 class="section-title">${award} (${filtered.length})</h2>${participantRows(filtered, true)}`
      : "";
  }).join("");

  showPage(`
    <div class="panel">
      <h2>RESULTS & AWARDS - ${escapeHtml(depot)}</h2>
      ${summary}
      <h2 class="section-title">NAMELIST</h2>
      ${names || "<p>No records found.</p>"}
    </div>
  `, `RESULTS & AWARDS - ${depot}`, "results");
}

function showSearch() {
  showPage(`
    <div class="panel">
      <h2>QUICK SEARCH</h2>
      <p class="muted">Enter full NRIC or Tag Number.</p>
      <div class="search-box">
        <input id="searchInput" placeholder="e.g. 003 or S1234003C" />
        <button id="searchButton">Search Participant</button>
      </div>
    </div>
  `, "QUICK SEARCH", "search");

  document.getElementById("searchButton").addEventListener("click", findParticipant);
  document.getElementById("searchInput").addEventListener("keydown", event => {
    if (event.key === "Enter") findParticipant();
  });
}

function findParticipant() {
  const query = document.getElementById("searchInput").value.trim().toLowerCase();
  const match = data.find(person =>
    String(person.tag).toLowerCase() === query ||
    String(person.nric).toLowerCase() === query
  );

  if (match) {
    showScorecard(match.tag);
  } else {
    showPage(`
      <div class="panel">
        <h2>No Result Found</h2>
        <p>Please check the full NRIC or Tag Number.</p>
      </div>
    `, "NO RESULT", "search");
  }
}

function showScorecard(tag) {
  const person = data.find(item => String(item.tag) === String(tag));
  if (!person) return;

  showPage(`
    <div class="panel">
      <h2>#${escapeHtml(person.tag)} - ${escapeHtml(person.name)}</h2>
      <p class="muted">${escapeHtml(person.depot)} · NRIC ${escapeHtml(person.nric)} · ${escapeHtml(person.serviceStatus)}</p>
      <div class="grid">
        <div class="box"><small>Total Score</small><strong>${person.score}</strong></div>
        <div class="box ${awardClass(person.award)}"><small>Final Award</small><strong>${escapeHtml(person.award)}</strong></div>
        <div class="box"><small>Sit-up</small><strong>${person.situp}</strong></div>
        <div class="box"><small>Sit-up Score</small><strong>${person.situpScore}</strong></div>
        <div class="box"><small>Push-up</small><strong>${person.pushup}</strong></div>
        <div class="box"><small>Push-up Score</small><strong>${person.pushupScore}</strong></div>
        <div class="box"><small>2.4km Run</small><strong>${person.run}</strong></div>
        <div class="box"><small>Run Score</small><strong>${person.runScore}</strong></div>
      </div>
    </div>
  `, "SCORECARD", "search");
}

