function parseCsv(text) {
  const rows = [];
  let row = [];
  let value = "";
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const next = text[i + 1];

    if (char === '"' && inQuotes && next === '"') {
      value += '"';
      i++;
    } else if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === "," && !inQuotes) {
      row.push(value);
      value = "";
    } else if ((char === "\n" || char === "\r") && !inQuotes) {
      if (value || row.length) {
        row.push(value);
        rows.push(row);
        row = [];
        value = "";
      }
      if (char === "\r" && next === "\n") i++;
    } else {
      value += char;
    }
  }

  if (value || row.length) {
    row.push(value);
    rows.push(row);
  }

  return rows;
}

function normalizeHeader(header) {
  return String(header || "").trim().toLowerCase().replace(/\\s+/g, " ");
}

function getCell(row, headers, possibleNames) {
  for (const name of possibleNames) {
    const index = headers.indexOf(normalizeHeader(name));
    if (index >= 0) return row[index] || "";
  }
  return "";
}

function formatRunTime(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";

  const timeMatch = raw.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/);
  if (timeMatch) {
    const first = Number(timeMatch[1]);
    const second = Number(timeMatch[2]);
    const third = timeMatch[3] !== undefined ? Number(timeMatch[3]) : null;

    if (third !== null) {
      const totalSeconds = (first * 3600) + (second * 60) + third;
      const minutes = Math.floor(totalSeconds / 60);
      const seconds = totalSeconds % 60;
      return `${minutes}:${String(seconds).padStart(2, "0")}`;
    }

    return `${first}:${String(second).padStart(2, "0")}`;
  }

  const numeric = Number(raw);
  if (!Number.isNaN(numeric) && numeric > 0 && numeric < 1) {
    const totalSeconds = Math.round(numeric * 24 * 60 * 60);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}:${String(seconds).padStart(2, "0")}`;
  }

  const embeddedTime = raw.match(/(\d{1,2}:\d{2}(?::\d{2})?)/);
  if (embeddedTime) {
    return formatRunTime(embeddedTime[1]);
  }

  return raw;
}

function normalizeAward(value) {
  const award = String(value || "").trim();
  if (!award) return "Did Not Attempt";
  if (award.toLowerCase() === "dna") return "Did Not Attempt";
  return award;
}

function buildParticipantsFromCsv(csvText) {
  const rows = parseCsv(csvText);

  const headerIndex = rows.findIndex(row => {
    const normalized = row.map(normalizeHeader);
    return normalized.includes("tag number") && normalized.includes("full name");
  });

  if (headerIndex < 0) {
    throw new Error("Could not find header row containing Tag Number and Full Name.");
  }

  const headers = rows[headerIndex].map(normalizeHeader);
  const participants = [];

  for (const row of rows.slice(headerIndex + 1)) {
    const tag = String(getCell(row, headers, ["Tag Number"])).trim();
    const name = String(getCell(row, headers, ["Full Name"])).trim();

    if (!tag || !name) continue;

    const rawScore = getCell(row, headers, ["Total Score"]);
    const score = Number(rawScore) || 0;

    participants.push({
      tag: /^\\d+$/.test(tag) ? tag.padStart(3, "0") : tag,
      depot: String(getCell(row, headers, ["Depot"])).trim(),
      name,
      nric: String(getCell(row, headers, ["Full NRIC", "NRIC"])).trim(),
      serviceStatus: String(getCell(row, headers, ["Service Status"])).trim(),
      situp: getCell(row, headers, ["Sit-up (Reps)", "Sit-up Reps"]),
      situpScore: getCell(row, headers, ["Sit-up Score", "Score"]),
      pushup: getCell(row, headers, ["Push-up (Reps)", "Push-up Reps"]),
      pushupScore: getCell(row, headers, ["Push-up Score", "Score_11"]),
      run: formatRunTime(getCell(row, headers, ["2.4km (Rounded Timing)", "2.4km Rounded Time", "2.4km Rounded Timing"])),
      runScore: getCell(row, headers, ["Run Score", "Score_13"]),
      score,
      award: normalizeAward(getCell(row, headers, ["FinalAward", "Final Award"])),
      remarks: String(getCell(row, headers, ["Remarks"])).trim()
    });
  }

  return participants;
}

function buildDepots(participants) {
  const preferred = ["Bn HQ", "91FMD", "92FMD", "93FMD", "SIO", "OES", "Attached In"];
  const found = [];

  for (const depot of preferred) {
    if (participants.some(person => person.depot === depot)) found.push(depot);
  }

  for (const depot of [...new Set(participants.map(person => person.depot).filter(Boolean))].sort()) {
    if (!found.includes(depot)) found.push(depot);
  }

  return found;
}

async function loadFromGoogleSheet() {
  const config = window.GOOGLE_SHEET_CONFIG || {};
  if (!config.enabled) return false;

  const url = `https://docs.google.com/spreadsheets/d/${config.sheetId}/gviz/tq?tqx=out:csv&gid=${config.gid}`;

  const response = await fetch(url);
  if (!response.ok) {
    throw new Error("Google Sheet CSV could not be loaded.");
  }

  const csvText = await response.text();
  const participants = buildParticipantsFromCsv(csvText);

  if (!participants.length) {
    throw new Error("No participants found in Google Sheet.");
  }

  data = participants;
  depots = buildDepots(participants);
  return true;
}

